<!--
 * 部门管理页面 — 树形表格展示部门层级，支持新增（顶级/子级）/编辑/删除部门
 *
 * @path apps\userinfo-web\src\views\system\dept\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 部门（列表页）
 * <p>部门（{@code ydsz_dept}）的列表页，消费后端契约 DepartmentController
 * （src/api/department.ts，auto-generated by bash/gen-contract.py）：
 * 以 tree() 获取带 children 的部门树直接渲染树形表格，支持新增顶级/子级部门、
 * 编辑与删除，删除成功后刷新树。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElMessage,
  ElMessageBox,
  ElTable,
  ElTableColumn,
  ElTag,
} from 'element-plus';
import { onMounted, ref } from 'vue';

import { remove, tree } from '#/api/department';
import type { DepartmentTreeVO } from '#/api/models';

import DeptForm from './dept-form.vue';

defineOptions({ name: 'DeptManagement' });

/** 判断部门状态是否启用（契约 status 为字符串 '1'/'0'） */
function isEnabled(status?: string): boolean {
  return status === '1';
}

const loading = ref(false);
const tableData = ref<DepartmentTreeVO[]>([]);

async function loadData() {
  loading.value = true;
  try {
    tableData.value = (await tree()) ?? [];
  } finally {
    loading.value = false;
  }
}

onMounted(loadData);

// ========== 表单弹窗 ==========
const [DeptFormModal, deptFormApi] = useYDSZModal({
  connectedComponent: DeptForm,
});

function handleAdd(parentId?: string) {
  deptFormApi.setData({
    parentId,
    treeData: tableData.value,
  });
  deptFormApi.open();
}

function handleEdit(row: DepartmentTreeVO) {
  deptFormApi.setData({
    record: row,
    treeData: tableData.value,
  });
  deptFormApi.open();
}

// ========== 删除 ==========
async function handleDelete(row: DepartmentTreeVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(
      `确定删除部门「${row.deptName ?? ''}」吗？`,
      '删除确认',
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await remove({ id: row.id });
    ElMessage.success('删除成功');
    loadData();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <div class="p-4">
      <div class="mb-4 flex items-center justify-between">
        <h3 class="text-lg font-semibold">部门管理</h3>
        <div class="flex gap-2">
          <ElButton @click="loadData">刷新</ElButton>
          <ElButton type="primary" @click="handleAdd()">新增顶级部门</ElButton>
        </div>
      </div>
      <ElTable
        v-loading="loading"
        :data="tableData"
        row-key="id"
        border
        default-expand-all
        :tree-props="{ children: 'children' }"
      >
        <ElTableColumn prop="deptName" label="部门名称" min-width="200" />
        <ElTableColumn prop="deptCode" label="部门编码" width="140" />
        <ElTableColumn prop="description" label="描述" min-width="180" />
        <ElTableColumn prop="sortOrder" label="排序" width="80" align="center" />
        <ElTableColumn label="状态" width="80" align="center">
          <template #default="{ row }">
            <ElTag :type="isEnabled(row.status) ? 'success' : 'danger'" size="small">
              {{ isEnabled(row.status) ? '启用' : '禁用' }}
            </ElTag>
          </template>
        </ElTableColumn>
        <ElTableColumn label="操作" width="240" fixed="right">
          <template #default="{ row }">
            <ElButton size="small" link type="primary" @click="handleAdd(row.id)">
              新增子部门
            </ElButton>
            <ElButton size="small" link type="primary" @click="handleEdit(row)">
              编辑
            </ElButton>
            <ElButton size="small" link type="danger" @click="handleDelete(row)">
              删除
            </ElButton>
          </template>
        </ElTableColumn>
      </ElTable>
    </div>
    <DeptFormModal @success="loadData" />
  </Page>
</template>